import { useEffect, useState } from "react";
import { Col, Container, Row } from "react-bootstrap";
import { useDispatch, useSelector } from "react-redux";
import { useDiscount } from "../hooks/useAuth";
import { ENDPOINTS } from "../app/config/config";
import trackEvent from '../utils/trackEvent';
import PopupDialog from "../components/popupdialog";

import {
  clearCart,
  addToCart,
  decreaseQty,
  deleteProduct,
} from "../app/features/cart/cartSlice";


const Cart = () => {
  const { cartList } = useSelector((state) => state.cart);
  trackEvent("navigated_to_cart")
  const flag = localStorage.getItem("wheelDiscount")
  const isGame = localStorage.getItem('appVersion') === "gamification";

  console.log("Q12334" + flag)
  const dispatch = useDispatch();
  const disc = useDiscount()
  // middlware to localStorage
  const totalPrice = cartList.reduce(
    (price, item) => price + item.qty * item.price,
    0
  );
  const [isDialogOpen, setIsDialogOpen] = useState(false);

  const [discount, setDiscount] = useState(0);
  const [discountAmount, setDiscountAmount] = useState(0);
  const [shipping, setShipping] = useState(40);

  const [finalPrice, setFinalPrice] = useState(0);


  const openDialog = () => {
    setIsDialogOpen(true);
  };

  const closeDialog = () => {
    setIsDialogOpen(false);
  };

  useEffect(()=>{
     const reviewDisc = Math.min((disc.reviews/ 10) * 5, 15) >= 5? Math.min((disc.reviews/ 10) * 5, 15): 0
     const wheelDiscount = 25
     const isRevierer =  localStorage.getItem("freeShipper") !== null
     if(isGame) {
      let amount;
      if(flag === "set") {
        setDiscount(wheelDiscount);
        amount = (totalPrice * wheelDiscount) / 100
      } else {
        setDiscount(reviewDisc)
        amount = (totalPrice * reviewDisc) / 100
      }
      setDiscountAmount(amount);
      if(isRevierer) {
        setShipping(0)
        setFinalPrice(totalPrice - amount)
      } else {
        setFinalPrice(totalPrice +shipping - amount)
      }
      
     } else {
      setFinalPrice(totalPrice +shipping)
     }

  },[])

 


  const handlePurchase = async () => {
    if (cartList.length === 0) {
      alert("Your cart is empty!");
      return;
    }

    try {

      let name;
      cartList.map(item => {
        if(item.name !== undefined) {
         name+=item.name + "x"+item.qty +","
         
        }

      })
      const response = await fetch(ENDPOINTS.Products+"/purchase", {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({ discount:discount,price:finalPrice,product_name: name,
           username: JSON.parse(localStorage.getItem('user')).username }),
    });

      if (response.status === 200  || response.status === 201) {
        trackEvent("purchase_made")
        // dispatch(clearCart()); // Clear cart after successful purchase
        
        cartList.map(item => {
            dispatch(deleteProduct(item))
  
        })
      } else {
      }
    } catch (error) {
      console.error("Error purchasing items:", error);
       openDialog()
    }
  };
  useEffect(() => {
    window.scrollTo(0, 0);
    // if(CartItem.length ===0) {
    //   const storedCart = localStorage.getItem("cartItem");
    //   setCartItem(JSON.parse(storedCart));
    // }
  }, []);
  return (
    <section className="cart-items">

<PopupDialog
        isOpen={isDialogOpen}
        onClose={closeDialog}
        title="Προειδοποίηση!"
        message="Πρέπει να κάνεις εγγραφή για να αγοράσεις"
      />
    <Container>
      <Row className="full-cart justify-content-center">
        <Col md={8}>
          {cartList.length === 0 && (
            <h1 className="no-items product">No Items in Cart</h1>
          )}
          { cartList.map((item) => {
            const productQty = item.price * item.qty;
            return (
              <div className="cart-list" key={item.id}>
                <Row>
                  <Col className="image-holder" sm={4} md={3}>
                    <img src={item.image_url} alt="" />
                  </Col>
                  <Col sm={8} md={9}>
                    <Row className="cart-content justify-content-center">
                      <Col xs={12} sm={9} className="cart-details">
                        <h3>{item.name}</h3>
                        <h4>
                          ${item.price}.00 * {item.qty}
                          <span>${productQty}.00</span>
                        </h4>
                      </Col>
                      <Col xs={12} sm={3} className="cartControl">
                        <button
                          className="incCart"
                          onClick={() =>
                            dispatch(addToCart({ product: item, num: 1 }))
                          }
                        >
                          <i className="fa-solid fa-plus"></i>
                        </button>
                        <button
                          className="desCart"
                          onClick={() => dispatch(decreaseQty(item))}
                        >
                          <i className="fa-solid fa-minus"></i>
                        </button>
                      </Col>
                    </Row>
                  </Col>
                  <button
                    className="delete"
                    onClick={() => dispatch(deleteProduct(item))}
                  >
                    <ion-icon name="close"></ion-icon>
                  </button>
                </Row>
              </div>
            );
          })}
        </Col>
        <Col md={4}>
          <div className="cart-total">
            <h2>Καλάθι:</h2>
            <div className="d_flex">
              <h4>Τιμή προιόντων:</h4>
              <h3>${totalPrice.toFixed(2)}</h3>
            </div>
            {shipping > 0 &&(<div className="d_flex discount-info">
                <h4>Έξοδα Αποστολής:</h4>
                <h3>+ ${shipping.toFixed(2)}</h3>
              </div>)}

            {isGame && discount > 0 && (
              <div className="d_flex discount-info">
                <h4>Έκπτωση ({discount.toFixed(2)}%):</h4>
                <h3>- ${discountAmount.toFixed(2)}</h3>
              </div>
            ) }
                        <div className="d_flex final-price">
              <h4>Τελική τιμή:</h4>
              <h3>${finalPrice.toFixed(2)}</h3>
            </div>


            <button className="buy-button" onClick={handlePurchase}>
              <i className="fa-solid fa-shopping-cart"></i> Αγόρασε τώρα
            </button>
          </div>
        </Col>
      </Row>
    </Container>
  </section>
  );
};

export default Cart;
